export const wissenSlugs = wissenTerms.map((t) => t.slug);

export function getWissenTerm(slug: string): WissenTerm | undefined {
  return wissenTerms.find((t) => t.slug === slug);
}

export function getDefaultWissenSlug(): string {
  return wissenTerms[0]?.slug ?? "positionierung";
}
